import gzip
from html import escape
from format_lecon import R,paras
def texte(n):return gzip.open(R/f'ressources_ia/aips/fi_fr/{n}.txt.gz','rt').read()
def citation(s):return '<blockquote><p>« '+escape(s.strip())+' »</p></blockquote>'
def ligne(s,p):
 t=[x for x in s.splitlines() if x.startswith(p)];assert len(t)==1,(p,len(t));return citation(t[0])
def zone(s,a,b):
 start=s.index(a)+len(a);return citation(s[start:s.index(b,start)])
def pti(l):
 s=texte(58314)
 body=paras('Privigen est une immunoglobuline humaine normale à 100 mg/ml, en perfusion intraveineuse. L’indication suisse couvre la thrombocytopénie immune primaire chez l’enfant et l’adulte à risque hémorragique élevé, ou avant un acte chirurgical.', 'Posologie AIPS pour l’épisode aigu :')+ligne(s,'Pour le traitement d’un épisode aigu'.replace('’',"'"))+paras('Le tableau AIPS confirme que la seconde option est une dose quotidienne ; ce sont deux schémas alternatifs, pas une addition :')+zone(s,'Traitement immunomodulateur\nThrombocytopénie immune primaire (TIP)\n','\nSyndrome de Guillain-Barré')+paras('Débit initial et augmentation, citations AIPS :')+ligne(s,'Le débit de perfusion initial de Privigen')+ligne(s,'En cas de bonne tolérance, le débit de perfusion peut')+paras('Le débit supérieur réservé dans la fiche à certains déficits immunitaires n’est pas transposé au PTI.', 'Enfant et adolescent, citation AIPS :')+ligne(s,'La posologie recommandée chez les enfants')+paras('Le PNDS pédiatrique français privilégie des formulations moins concentrées pour son schéma. Cette recommandation ne transforme pas Privigen 10 % en solution 5 % ; choix du produit et débit relèvent de l’équipe pédiatrique.', 'Contre-indications AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Prévoir hydratation adaptée, surveillance rénale, risque thrombotique, hémolyse et réactions de perfusion. Une céphalée sévère avec raideur de nuque après perfusion nécessite une évaluation, notamment pour méningite aseptique.', 'Surveiller pendant et après la perfusion ; ralentir ou interrompre en cas de réaction. Documenter le produit et le numéro de lot. Les vaccins vivants peuvent être moins efficaces après immunoglobulines ; organiser leur calendrier.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')
 a=l.subwindow('privigen','Privigen : dose et sécurité',body,(21,22,23))
 s=texte(29349)
 body=paras('La prednisone est un corticoïde utilisé en première ligne dans le PNDS adulte. L’AIPS Prednisone Streuli mentionne la thrombocytopénie idiopathique, mais ne fournit pas un schéma propre au PTI dans sa rubrique posologique.', 'Principe de dose de la fiche suisse, cité sans transformer une dose générale en protocole du PTI :')+ligne(s,'Prednisone Streuli doit être dosé')+paras('Le protocole de dose, durée et arrêt doit donc être précisé par l’hématologue selon le contexte. Les pourcentages pédiatriques généraux de cette fiche ne sont pas transposés à un PTI de l’enfant.', 'Contre-indications AIPS, avec leur distinction entre urgence et utilisation prolongée :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Surveiller infections, glycémie, pression artérielle, troubles de l’humeur et effets digestifs ; éviter la prolongation non planifiée. Une association médicamenteuse ou une vaccination demande une vérification spécifique.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')
 b=l.subwindow('prednisone','Prednisone : cadre suisse et limites',body,(21,24))
 return a+' ; '+b
def willebrand(l):
 s=texte(52711)
 body=paras('Octostim 15 µg injectable contient de la desmopressine acétate. Son effet libère des facteurs endogènes : la réponse doit être évaluée dans le type de maladie identifié.', 'Périmètre de l’indication suisse, citation AIPS :')+zone(s,'\nIndications/Possibilités d’emploi\n','\nPosologie/Mode d’emploi')+paras('La rubrique d’indication vise notamment le type I dans le contexte préopératoire ou posttraumatique. Une épistaxis spontanée ne doit pas être présentée sans nuance comme une indication autonome explicitement libellée ici ; le centre vérifie le cadre du traitement individuel.', 'Injection intraveineuse, citation AIPS :')+zone(s,'\nInjection intraveineuse\n','\nPerfusion')+paras('Répétition, citation AIPS :')+ligne(s,"En cas d'effet positif, la dose initiale")+paras('Ces doses ne se transposent pas aux pulvérisations nasales. La voie sous-cutanée possède ses propres instructions dans la fiche ; cette fenêtre décrit la voie intraveineuse.', 'Contre-indications et limites d’efficacité, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Restreindre les apports liquidiens selon le plan prescrit et surveiller sodium, poids, osmolalité, pression artérielle et réponse hémostatique. Une rétention d’eau peut provoquer hyponatrémie, convulsions ou coma ; les jeunes enfants et personnes âgées sont particulièrement sensibles.', 'L’effet diminue avec les répétitions ; une hémostase prolongée nécessite de réévaluer la stratégie. Vérifier les traitements qui renforcent l’effet antidiurétique, notamment certains psychotropes et anti-inflammatoires.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')
 a=l.subwindow('octostim','Octostim : indication, voie et vigilance',body,(25,))
 s=texte(45780)
 body=paras('Haemate P apporte du facteur de von Willebrand et du facteur VIII. L’indication suisse couvre la prévention et le traitement des hémorragies lorsque la desmopressine seule est inefficace ou contre-indiquée.', 'La dose doit être calculée dans l’unité du facteur visé, sans confondre les deux valeurs imprimées sur le flacon. Le spécialiste suit les activités des deux facteurs.', 'Posologie du syndrome de von Willebrand, citation AIPS :')+zone(s,'\nSyndrome de von Willebrand\n','\nEn cas de déficience en facteur VIII')+paras('Ne pas employer ici le tableau de traitement de l’hémophilie A comme s’il s’agissait de la posologie Willebrand.', 'Voie intraveineuse ; vitesse maximale, citation AIPS :')+ligne(s,"La vitesse maximale d'injection ne doit pas")+paras('Contre-indication AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Surveiller hypersensibilité, événements thrombotiques et augmentation excessive du facteur VIII lors des administrations répétées. En cas de réponse insuffisante, rechercher des inhibiteurs avec le centre spécialisé.', 'Documenter le numéro de lot ; malgré les mesures de sécurisation du plasma, un risque infectieux résiduel ne peut être totalement exclu. Vérifier la vaccination contre les hépatites A et B lors de traitements plasmatiques réguliers.', 'Grossesse et allaitement : la fiche réserve l’administration à une indication explicite. Des hémorragies tardives du post-partum restent possibles ; le suivi obstétrical et hématologique ne s’arrête pas à l’accouchement.')
 b=l.subwindow('haemate','Haemate P : unités et surveillance',body,(26,))
 return a+' ; '+b+' ; <a href="LOT_021_Phase_A_V0.html#a-med13">acide tranexamique oral : fiche suisse du cours</a>'
